Given a stack of integers, sort it in ascending order using another temporary stack.Examples: Input: [34, 3, 31, 98, 92, 23]Output: [3, 23, 31, 34, 92, 98]Explanation: After Sorting the given array it would be look like as [3, 23, 31, 34, 92, 98]Input: [3, 5, 1, 4, 2, 8]Output: [1, 2, 3, 4, 5, 8] Try It YourselfApproach:To sort a stack of intergers using an extra stack (tmpStack), first, create an empty tmpStack. Then, while the input stack is not empty, pop the top element (temp). If tmpStack has smaller elements on top, move them back to the input stack. Finally, push temp into tmpStack. Repeat this process until all elements are sorted in tmpStack in ascending order.Create a temporary stack say tmpStack.While input stack is NOT empty do this: Pop an element from input stack call it tempWhile temporary stack is NOT empty and top of temporary stack is less than temp, pop from temporary stack and push it to the input stackPush temp in temporary stackThe sorted numbers are in tmpStackinput: [34, 3, 31, 98, 92, 23]Element taken out: 23input: [34, 3, 31, 98, 92]tmpStack: [23]Element taken out: 92input: [34, 3, 31, 98]tmpStack: [23, 92]Element taken out: 98input: [34, 3, 31]tmpStack: [23, 92, 98]Element taken out: 31input: [34, 3, 98, 92]tmpStack: [23, 31]Element taken out: 92input: [34, 3, 98]tmpStack: [23, 31, 92]Element taken out: 98input: [34, 3]tmpStack: [23, 31, 92, 98]Element taken out: 3input: [34, 98, 92, 31, 23]tmpStack: [3]Element taken out: 23input: [34, 98, 92, 31]tmpStack: [3, 23]Element taken out: 31input: [34, 98, 92]tmpStack: [3, 23, 31]Element taken out: 92input: [34, 98]tmpStack: [3, 23, 31, 92]Element taken out: 98input: [34]tmpStack: [3, 23, 31, 92, 98]Element taken out: 34input: [98, 92]tmpStack: [3, 23, 31, 34]Element taken out: 92input: [98]tmpStack: [3, 23, 31, 34, 92]Element taken out: 98input: []tmpStack: [3, 23, 31, 34, 92, 98]Final sorted stack: [3, 23, 31, 34, 92, 98]
            C++

    #include <bits/stdc++.h>
using namespace std;

// This function return the sorted stack
stack<int> sortStack(stack<int> &input)
{
    stack<int> tmpStack;

    while (!input.empty())
    {
        // pop out the first element
        int tmp = input.top();
        input.pop();

        // while temporary stack is not empty and top
        // of stack is lesser than temp
        while (!tmpStack.empty() && tmpStack.top() < tmp)
        {
            // pop from temporary stack and push
            // it to the input stack
            input.push(tmpStack.top());
            tmpStack.pop();
        }

        // push temp in temporary of stack
        tmpStack.push(tmp);
    }

    return tmpStack;
}

// main function
int main()
{
    stack<int> input;
    input.push(34);
    input.push(3);
    input.push(31);
    input.push(98);
    input.push(92);
    input.push(23);

    // This is the temporary stack
    stack<int> tmpStack = sortStack(input);
    while (!tmpStack.empty())
    {
        cout << tmpStack.top()<< " ";
        tmpStack.pop();
    }
}


